import React, { useMemo, useState } from 'react';
import EventCard from './EventCard';

export default function ListView({ events }) {
  const [search, setSearch] = useState('');
  const [selectedTag, setSelectedTag] = useState(null);

  const allTags = useMemo(() => {
    const set = new Set();
    events.forEach(e => e.tags.forEach(t => set.add(t)));
    return Array.from(set).sort();
  }, [events]);

  const filtered = useMemo(() => {
    return events.filter(e => {
      const q = search.toLowerCase();
      const matchSearch = !q || e.name.toLowerCase().includes(q) || e.city.toLowerCase().includes(q) || e.country.toLowerCase().includes(q);
      const matchTag = !selectedTag || e.tags.includes(selectedTag);
      return matchSearch && matchTag;
    });
  }, [events, search, selectedTag]);

  // Group by country → city
  const grouped = useMemo(() => {
    const map = {};
    filtered.forEach(e => {
      if (!map[e.country]) map[e.country] = {};
      if (!map[e.country][e.city]) map[e.country][e.city] = [];
      map[e.country][e.city].push(e);
    });
    // Sort countries and cities alphabetically
    const sorted = {};
    Object.keys(map).sort().forEach(country => {
      sorted[country] = {};
      Object.keys(map[country]).sort().forEach(city => {
        sorted[country][city] = map[country][city];
      });
    });
    return sorted;
  }, [filtered]);

  return (
    <div style={{ maxWidth: 800, margin: '0 auto', padding: '32px 24px' }}>
      {/* Search + filters */}
      <div style={{ marginBottom: 28 }}>
        <input
          type="text"
          placeholder="Rechercher un événement, une ville, un pays…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{
            width: '100%', padding: '10px 14px', fontSize: 14,
            border: '1px solid var(--border)', borderRadius: 'var(--radius-md)',
            background: 'var(--surface)', color: 'var(--text-primary)',
            outline: 'none', marginBottom: 14,
          }}
        />
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
          <button
            onClick={() => setSelectedTag(null)}
            style={{
              fontSize: 12, padding: '4px 10px', borderRadius: 99, cursor: 'pointer',
              border: `1px solid ${!selectedTag ? 'var(--accent)' : 'var(--border)'}`,
              background: !selectedTag ? 'var(--accent-light)' : 'var(--surface)',
              color: !selectedTag ? 'var(--accent-text)' : 'var(--text-secondary)',
            }}
          >
            Tous
          </button>
          {allTags.map(tag => (
            <button
              key={tag}
              onClick={() => setSelectedTag(tag === selectedTag ? null : tag)}
              style={{
                fontSize: 12, padding: '4px 10px', borderRadius: 99, cursor: 'pointer',
                border: `1px solid ${selectedTag === tag ? 'var(--accent)' : 'var(--border)'}`,
                background: selectedTag === tag ? 'var(--accent-light)' : 'var(--surface)',
                color: selectedTag === tag ? 'var(--accent-text)' : 'var(--text-secondary)',
              }}
            >
              {tag}
            </button>
          ))}
        </div>
      </div>

      {/* Results count */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '48px 0', fontSize: 14 }}>
          Aucun événement trouvé.
        </div>
      ) : (
        <>
          <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 24 }}>
            {filtered.length} événement{filtered.length > 1 ? 's' : ''} · {Object.keys(grouped).length} pays
          </div>

          {/* Grouped list */}
          {Object.entries(grouped).map(([country, cities]) => (
            <div key={country} style={{ marginBottom: 36 }}>
              {/* Country header */}
              <div style={{
                display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16
              }}>
                <h2 style={{ fontSize: 18, fontWeight: 700, color: 'var(--text-primary)' }}>
                  {country}
                </h2>
                <span style={{
                  fontSize: 11, padding: '2px 8px', borderRadius: 99,
                  background: 'var(--border)', color: 'var(--text-muted)',
                }}>
                  {Object.values(cities).flat().length} événement{Object.values(cities).flat().length > 1 ? 's' : ''}
                </span>
              </div>

              {Object.entries(cities).map(([city, cityEvents]) => (
                <div key={city} style={{ marginBottom: 20 }}>
                  {/* City header */}
                  <div style={{
                    display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10,
                    paddingLeft: 12, borderLeft: '2px solid var(--accent)'
                  }}>
                    <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-secondary)' }}>
                      📍 {city}
                    </span>
                  </div>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: 10, paddingLeft: 12 }}>
                    {cityEvents.map(ev => (
                      <EventCard key={ev.id} event={ev} />
                    ))}
                  </div>
                </div>
              ))}
            </div>
          ))}
        </>
      )}
    </div>
  );
}
